import{_ as o,l as n,o as l,c as s,v as d,p,x as r,d as t,i as h,S as m,b as a}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"T5 相对位置偏置","description":"","frontmatter":{"title":"T5 相对位置偏置","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/t5-relative-bias.md","filePath":"llm/t5-relative-bias.md","lastUpdated":1789023840000}'),f={name:"llm/t5-relative-bias.md"};function c(A,e,E,u,B,b){const i=n("Mermaid");return l(),s("div",null,[e[1]||(e[1]=d('<h1 id="t5-相对位置偏置" tabindex="-1">T5 相对位置偏置 <a class="header-anchor" href="#t5-相对位置偏置" aria-label="Permalink to &quot;T5 相对位置偏置&quot;">​</a></h1><div class="epigraph"><p>我们不用正弦或学习到的绝对位置嵌入，而是在注意力 logits 上加一个随距离变化的标量偏置。</p><footer>—— Raffel et al., Exploring the Limits of Transfer Learning with a Unified Text-to-Text Transformer, JMLR 2020</footer></div><p><a href="/llm/bert-encoder">上一课</a>把双向编码器的层序、段嵌入和 <code>[CLS]</code> 钉死。位置仍是可学习绝对向量，加在嵌入上，最长 512。本课补的缺口：编解码模型若要把任意长度的源与目标送进同一套注意力，绝对下标会先饱和，段嵌入也帮不上跨序列的相对距离。T5 把位置从「加在输入上的向量」改成「加在注意力分数上的偏置」。后课的 BART、前缀掩码都默认你会这种 logits 侧的相对位置，不再回到 BERT 的绝对表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/bert-encoder">BERT 编码器</a>的位置嵌入 \\(p_i\\in\\mathbb{R}^d\\) 与 token 相加，位置是内容的一部分。<a href="/llm/sinusoidal-pe">正弦位置</a>同样作用在输入，只是用封闭公式生成。两种都把「第 \\(i\\) 个槽」当成绝对坐标。编码器–解码器里源长 \\(m\\)、目标长 \\(n\\) 经常超过预训练截断；绝对坐标一溢出，模型看见的是从未训练过的下标，而不是「相距 \\(k\\) 步」。</p><p>Shaw 等人已经把相对位置写进注意力：让 \\(q_i\\) 与 \\(k_j\\) 的相容性依赖 \\(j-i\\)。T5 要的更窄——不必学一组相对键向量，只要在 <a href="/llm/sdpa">SDPA</a> 的分数上加一个标量，让距离成为打分的加性修正。缺口是：<strong>位置信息进 logits，不进嵌入和</strong>。</p><p><span class="marginnote">ALiBi 也是 logits 侧的线性偏置，但是固定斜率、不学习分桶。T5 的偏置可学习、按距离分桶。后课比较外推时不要把两者收成同一种方法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记分数 \\(S_{ij}=q_i^\\top k_j/\\sqrt{d_k}\\)。T5 写成</p> \\[S_{ij}\\leftarrow S_{ij}+b_{\\mathrm{bucket}(j-i)}, \\]<p>\\(b\\) 是每个注意力头一份的可学习向量，下标由距离分桶给出。分桶对近距离一一对应，远距离对数压缩，避免为每个可能的 \\(|j-i|\\) 各养一个参数。编码器自注意力、解码器掩码自注意力、<a href="/llm/encoder-decoder-attention">编码器–解码器注意力</a> 各用自己的偏置表；交叉注意力里 \\(i\\) 与 \\(j\\) 分属目标与源，桶仍按相对偏移，不按绝对下标对齐。</p><p>嵌入层不再加位置向量。内容与位置在加法上解耦：token 嵌入只编码身份，距离只改谁更容易被看见。</p><h3 id="分桶而不是全表" tabindex="-1">分桶而不是全表 <a class="header-anchor" href="#分桶而不是全表" aria-label="Permalink to &quot;分桶而不是全表&quot;">​</a></h3><p>若为每个偏移存一个 \\(b\\)，最大长度一涨，参数与缓存都涨。对数分桶把「很远」收成少数几个共享偏置，表达的是粗粒度的远距先验，不是精确的第 407 步。这是相对偏置能接到 512 以外的代价：远距分辨率下降。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相对偏置不改变 softmax 的行随机性，只改变哪一列在竞争中占优。头与头可以学到不同的距离偏好：有的头偏近邻，有的头几乎平坦。因为偏置加在缩放点积之后、softmax 之前，它与因果掩码相容——非法位置仍是 \\(-\\infty\\)，合法位置内部再按距离微调。</p><p>交叉注意力里源与目标没有共享绝对坐标，相对桶提供的是「源侧第几段更像在对齐当前目标位置」的软先验，不是对齐算法本身。对齐仍由内容点积做；偏置只是打破完全无位置时的置换对称。</p><p><span class="marginnote">置换对称：若既无位置嵌入也无相对偏置，交换两个源 token 只改内容项。相对偏置让「左边的源」和「右边的源」在分数上可区分，即便内容相似。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>相对偏置不是长度外推的保证。桶表在训练长度内学到的远距值，推到更远时往往落在同一个桶，模型把「更远」当成「已经很远」。T5 的文本生成长度靠相对偏置加编解码结构共同撑起，不要单归因于 \\(b\\)。绝对位置在短编码器、句对分类里仍简单；本课不废除它，只是在编解码主干上换默认。</p>',20)),(l(),p(m,null,{default:r(()=>[h(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Query%22%5D%20--%3E%20S%5B%22%E7%BC%A9%E6%94%BE%E7%82%B9%E7%A7%AF%22%5D%0A%20%20K%5B%22Key%22%5D%20--%3E%20S%0A%20%20D%5B%22%E7%9B%B8%E5%AF%B9%E8%B7%9D%E7%A6%BB%E5%88%86%E6%A1%B6%22%5D%20--%3E%20B%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E5%81%8F%E7%BD%AE%20b%22%5D%0A%20%20S%20--%3E%20A%5B%22S%20%E5%8A%A0%20b%22%5D%0A%20%20B%20--%3E%20A%0A%20%20A%20--%3E%20M%5B%22%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20P%5B%22Softmax%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"T5 把位置从输入加法挪到注意力 logits 的相对标量偏置，按距离分桶、按头学习。"),a("li",null,"嵌入不再携带绝对下标；远距分辨率由桶的对数压缩决定。"),a("li",null,"编码器、解码器自注意力与交叉注意力各有偏置表，交叉注意力尤其需要它来打破无坐标的置换对称。"),a("li",null,"分桶能接到训练长度以外，但不等于外推已经解决。"),a("li",null,[t("出处：Raffel et al., "),a("em",null,"T5"),t(", JMLR 2020；相对位置的前身见 Shaw et al., NAACL 2018。")])],-1))])}const k=o(f,[["render",c]]);export{T as __pageData,k as default};
